      "descricao": "<p style=\"text-align: left;\">Quando for usar seus corpos amaldiçoados, você é capaz de mesclar dois deles, criando um modelo híbrido. Ele recebe os pontos de vida somados de ambos, o maior valor de movimento e de Classe de Armadura, adicionando seu bônus de maestria nela. Você consegue manter um modelo híbrido por uma quantidade de rodadas igual ao seu modificador de Carisma ou Sabedoria. Você pode usar essa habilidade um número de vezes igual ao seu modificador de Carisma ou Sabedoria por descanso longo. Um modelo híbrido pode também possuir habilidades exclusivas.</p>",
