      "descricao": "<p>Você sabe do valor das suas invocações, podendo até mesmo utilizar delas para sacrifícios em prol de si mesmas. Caso uma invocação sobre seu controle, dentro de um alcance igual a metade do Deslocamento de outra Invocação, vá receber dano suficiente para ser dissipada ou exorcizada, você pode gastar sua reação para fazer com que ela se mova até ficar adjacente a ela em receber esse dano por ela. Além disso, caso você esteja no alcance de ataque de uma invocação que foi atacada, você pode gastar sua reação também para reduzir o dano que ela receberá em um valor igual a Xd6 + seu modificador de Presença ou Sabedoria. X é igual ao seu bônus de treinamento.</p>",
