      "descricao": "<p>Você consegue unificar seus comandos para fazer com que suas invocações ataquem em conjunto. Uma vez por rodada, como uma Ação Comum, você pode fazer com que todas as suas invocações ativas utilizem uma ação de ataque contra um mesmo alvo, pagando 2PE para cada invocação além da primeira. Para cada invocação participando do ataque em conjunto, todas recebem um bônus de +1 na jogada de ataque. Você pode, também, optar por participar do Ataque em Conjunto caso o alvo esteja no seu alcance. Você pode usar essa habilidade uma quantidade de vezes igual ao seu modificador de Sabedoria ou Presença por descanso longo.</p>",
