      "descricao": "<p style=\"\">O seu companheiro amaldiçoado também recebe várias capacidades especiais, das quais você pode usar uma delas como ação livre:</p><ul><li><p>Curar a você em 2d10 + seu modificador de Sabedoria ou Presença. Nos níveis 5, 9, 13 e 17, a cura aumenta em +1d10.</p></li><li><p>Infligir 2d8 + seu modificador de Sabedoria ou Presença de dano em um inimigo dentro de 6 metros. No nível 5, esse dano aumenta para 4d8; no nível 9, aumenta para 5d10; no nível 13, aumenta para 8d8 e, no nível 17, aumenta para 8d10. O dano é de um tipo a sua escolha.</p></li><li><p>Forçar todos os inimigos dentro de 9 metros a realizarem um teste de resistência de Fortitude ou serem cegados por 2 turnos. Nos níveis 5, 9, 13 e 17, a área afetada aumenta em +3 metros.</p></li></ul><p style=\"\">Você pode utilizar cada um dos efeitos uma vez por descanso curto ou longo.</p>",
