      "descricao": "<p>Você se torna capaz de imbuir armas com a sua própria técnica, potencializandoas grandemente. Quando for utilizar um Feitiço de dano, que não seja de um tipo especial ou em área, você pode, como uma Ação Bônus, gastar 2 PE adicionais para a imbuir em uma arma que esteja manejando, desde que seja treinado com a arma e o Feitiço seja uma Ação Comum ou inferior. Se acertar o ataque, além de causar dano, você causa o efeito do Feitiço, como após ataque. Caso o Feitiço seja de TR, não será necessário um teste para efeito, aplicando-o diretamente, com exceção de Condições, que ainda irão exigir um TR.</p>",
