      "descricao": "<p style=\"\">Em certos momentos, ser imprudente e se desafiar o motiva a triunfar. Quando uma cena de combate se inicia, você pode escolher lutar com uma restrição imediata, sacrificando algo (por exemplo, a visão ou o movimento de uma das pernas), recebendo uma penalidade equivalente (condição cego ou uma penalidade de metade do movimento e -4 em rolagens de acrobacia), mas caso vença o combate com a restrição, você recupera uma quantidade de pontos de energia igual a 2 multiplicado pelo número de inimigos, com máximo igual ao seu nível de personagem; recebe +3 em rolagens de ataque e tem sua margem de crítico reduzida em 1 até o fim da missão atual.<br></p>",
