      "descricao": "<p>Se dedicando a avançar sem olhar para trás, você consegue usar da sua energia para o impulsionar em uma investida direta. Como uma ação completa, você gasta 6 PE para se mover até uma distância igual ao dobro do seu deslocamento; sempre que passar por uma criatura durante essa investida, ela deve realizar um teste de resistência de Reflexos, sofrendo Xd10 + modificador de Força ou Destreza (onde X é o seu bônus de treinamento) de dano de Impacto e não podendo realizar Ataques de Oportunidade contra você em uma falha. Ao terminar seu movimento adjacente a uma criatura, você pode realizar um ataque contra ela.</p>",
